  "Could not load the hotspot map. Change region or reload the page.": {"es": "No se pudo cargar el mapa de focos térmicos. Cambia de región o recarga la página.", "eu": "Ezin izan da bero-fokuen mapa kargatu. Aldatu eskualdea edo kargatu berriro orria."},
  "Choose a CSV or Parquet file.": {"es": "Elige un archivo CSV o Parquet.", "eu": "Aukeratu CSV edo Parquet fitxategi bat."},
  "The file is larger than 25 MiB.": {"es": "El archivo supera los 25 MiB.", "eu": "Fitxategiak 25 MiB baino gehiago ditu."},
  "An upload is being processed. Try again in a moment.": {"es": "Ya se está procesando un archivo. Vuelve a intentarlo en un momento.", "eu": "Fitxategi bat prozesatzen ari da. Saiatu berriro une bat barru."},
  "Save the CSV as UTF-8 and upload it again.": {"es": "Guarda el CSV en UTF-8 y vuelve a subirlo.", "eu": "Gorde CSV fitxategia UTF-8 formatuan eta igo berriro."},
  "The Parquet file could not be read.": {"es": "No se pudo leer el archivo Parquet.", "eu": "Ezin izan da Parquet fitxategia irakurri."},
  "The file needs too much memory to process. Try a smaller extract.": {"es": "El archivo requiere demasiada memoria. Prueba con un extracto más pequeño.", "eu": "Fitxategia prozesatzeko memoria gehiegi behar da. Saiatu zati txikiago batekin."},
  "Use at most 200,000 rows and 100 columns.": {"es": "Usa como máximo 200.000 filas y 100 columnas.", "eu": "Erabili gehienez 200.000 errenkada eta 100 zutabe."},
  "The uncompressed Parquet exceeds 128 MiB.": {"es": "El Parquet descomprimido supera los 128 MiB.", "eu": "Deskonprimitutako Parquet fitxategiak 128 MiB baino gehiago ditu."},
  "The sensor must be MODIS or VIIRS when supplied.": {"es": "Si indicas un sensor, debe ser MODIS o VIIRS.", "eu": "Sentsorea adierazten baduzu, MODIS edo VIIRS izan behar du."},
  "Unknown satellite. Use Terra, Aqua, S-NPP, NOAA-20 or NOAA-21.": {"es": "Satélite desconocido. Usa Terra, Aqua, S-NPP, NOAA-20 o NOAA-21.", "eu": "Satelite ezezaguna. Erabili Terra, Aqua, S-NPP, NOAA-20 edo NOAA-21."},
  "A sensor does not match the reported satellite.": {"es": "Un sensor no coincide con el satélite indicado.", "eu": "Sentsore bat ez dator bat adierazitako satelitearekin."},
  "The processing stream must be ARCHIVE or NRT when supplied.": {"es": "Si indicas el tipo de procesamiento, debe ser ARCHIVE o NRT.", "eu": "Prozesamendu-mota adierazten baduzu, ARCHIVE edo NRT izan behar du."},
  "Use observation years between 1900 and 2100.": {"es": "Usa años de observación entre 1900 y 2100.", "eu": "Erabili 1900 eta 2100 bitarteko behaketa-urteak."},
  "Region names must contain at most 80 characters.": {"es": "Los nombres de las regiones deben tener como máximo 80 caracteres.", "eu": "Eskualdeen izenek gehienez 80 karaktere izan ditzakete."},
  "Use at most 32 regions per upload.": {"es": "Usa como máximo 32 regiones por archivo.", "eu": "Erabili gehienez 32 eskualde fitxategi bakoitzean."},
  "The total number of detections is too large.": {"es": "El número total de detecciones es demasiado grande.", "eu": "Detekzioen kopuru osoa handiegia da."},
  "Each mapped row needs both a latitude and a longitude.": {"es": "Cada fila que se represente en el mapa necesita latitud y longitud.", "eu": "Mapan erakutsiko den errenkada bakoitzak latitudea eta longitudea behar ditu."},
  "The file has duplicate column names.": {"es": "El archivo tiene nombres de columnas duplicados.", "eu": "Fitxategiak zutabe-izen bikoiztuak ditu."},
  "The uploaded dataset is empty.": {"es": "El archivo cargado está vacío.", "eu": "Igotako fitxategia hutsik dago."},
  "Missing region identifier: dataset lacks 'region_id'/'region' and no explicit region was provided.": {"es": "Falta la región. Añade la columna «region_id» o «region», o indica la región en el formulario.", "eu": "Eskualdea falta da. Gehitu «region_id» edo «region» zutabea, edo adierazi eskualdea inprimakian."},
  "Ambiguous monthly schema: missing count column ('observations', 'detections', 'hotspot_count', or 'count').": {"es": "Al resumen mensual le falta la columna de recuento («observations», «detections», «hotspot_count» o «count»).", "eu": "Hileko laburpenari zenbaketaren zutabea falta zaio («observations», «detections», «hotspot_count» edo «count»)."},
  "Unrecognized dataset schema: expected ('year', 'month') or ('acq_date'/'date').": {"es": "Formato de datos desconocido. Usa «year» y «month», o una columna «acq_date» o «date».", "eu": "Datu-formatu ezezaguna. Erabili «year» eta «month» zutabeak, edo «acq_date» edo «date» zutabea."},
  "Invalid data: empty or null values found in '{column}'.": {"es": "Hay valores vacíos o nulos en «{column}».", "eu": "«{column}» zutabean balio hutsak edo nuluak daude."},
  "Invalid year value detected: '{value}'.": {"es": "El valor «{value}» no es un año válido.", "eu": "«{value}» ez da baliozko urtea."},
  "Invalid month value detected (must be 1-12): '{value}'.": {"es": "«{value}» no es un mes válido. Usa un número del 1 al 12.", "eu": "«{value}» ez da baliozko hilabetea. Erabili 1etik 12ra bitarteko zenbaki bat."},
  "Invalid date value detected in '{column}': '{value}'.": {"es": "«{value}» no es una fecha válida en «{column}».", "eu": "«{value}» ez da baliozko data «{column}» zutabean."},
  "Invalid count in '{column}': empty or null values are not allowed.": {"es": "«{column}» no admite recuentos vacíos o nulos.", "eu": "«{column}» zutabean ezin da zenbaketa hutsik edo balio nulurik egon."},
  "Invalid count in '{column}': non-numeric text '{value}' detected.": {"es": "«{value}» no es un recuento numérico en «{column}».", "eu": "«{value}» ez da zenbakizko balioa «{column}» zutabean."},
  "Invalid count in '{column}': negative value '{value}' detected.": {"es": "«{column}» no admite el recuento negativo «{value}».", "eu": "«{column}» zutabeak ez du onartzen «{value}» balio negatiboa."},
  "Invalid count in '{column}': fractional value '{value}' detected.": {"es": "«{column}» no admite el recuento fraccionario «{value}».", "eu": "«{column}» zutabeak ez du onartzen «{value}» zatiki-balioa."},
  "Invalid count in '{column}': use integers below 2⁶³.": {"es": "Usa números enteros menores que 2⁶³ en «{column}».", "eu": "Erabili 2⁶³ baino zenbaki oso txikiagoak «{column}» zutabean."},
  "Invalid {column} value: {value}.": {"es": "«{value}» no es un valor válido para «{column}».", "eu": "«{value}» ez da baliozkoa «{column}» zutabearentzat."},
